    expect((await fs.stat(specFile)).mtimeMs).toBe(specStat.mtimeMs);
    await expect(fs.access(f.transactionFile)).rejects.toMatchObject({ code: 'ENOENT' });
    const again = await archiveNativeSdkChange({
