      executorId: 'comet-native-checks',
      context: { requestId: 'child-checks', projectRoot: f.root },
    });
  }
  return {
    ...f,
    runtime,
    run,
    childWorktree,
    candidateCommit,
    check,
    interruptedOutput: () => interruptedOutput,
  };
}

