    const repairChecks = await executeNativePortableCheckPlan({
      paths: parentPaths,
      name: 'parent',
      plans: [],
    });
    const repairDispatch = await dispatchNativePortableVerifier({
      paths: parentPaths,
      name: 'parent',
      checks: repairChecks.checks,
    });
    const failedRepair = await submitNativePortableVerifierResult({
      paths: parentPaths,
      name: 'parent',
      checks: repairChecks.checks,
      maxVerifyFailures: 3,
      envelope: verifier.envelopeVerifierResponse({
        candidateId: repairDispatch.builder_handoff!.candidate_id,
        identity: verifier.captureExecutionIdentity({
          identityProvider: 'test-host',
          executionRef: 'parent-repair-verifier',
        }),
        payload: {
          kind: 'final-result',
          result: {
            iteration: repairDispatch.loop.iteration,
            attempt: repairDispatch.loop.attempt,
            verdict: 'fail',
            acceptance: repairDispatch.acceptance.map(({ id }, index) => ({
              id,
              result: index === 0 ? 'failed' : 'passed',
              reason: 'Actual parent verification result.',
            })),
            risks: [],
            summary: 'The Agent chooses to replan after another actual failure.',
          },
        },
      }),
    });
    const replanning = await nativeNextCommand(
      ['parent', '--revise-requirements', '--summary', 'Explicitly revise the repair child plan'],
      repository,
    );
    expect(data(replanning).state).toMatchObject({ phase: 'shape', acceptance: { total: 0 } });
    expect(
      (await readNativePortableChange(parentPaths, 'parent')).loop.failed_iteration_count,
    ).toBe(failedRepair.state.loop.failed_iteration_count);
    await expect(
      nativeNextCommand(
        ['parent', '--summary', 'Prepare the incomplete repair plan for confirmation'],
        repository,
      ),
    ).resolves.toMatchObject({
      exitCode: 0,
      data: { state: { phase: 'shape', status: 'await-user' } },
    });
    const replanned = await nativeNextCommand(
      await guardedShapeConfirmationArgs(
        parentPaths,
        'parent',
        'Confirm parent-owned integration repair',
      ),
      repository,
    );
    expect(data(replanned)).toMatchObject({ state: { phase: 'build' } });
    const confirmedRepair = await readNativePortableChange(parentPaths, 'parent');
    expect(confirmedRepair.loop.failed_iteration_count).toBe(
      failedRepair.state.loop.failed_iteration_count,
    );
    expect(confirmedRepair.children_contract?.children.map(({ name }) => name).sort()).toEqual([
      'child-a',
      'child-b',
      'child-c',
    ]);
    const repairedCandidate = await nativeNextCommand(
      ['parent', '--runner-input', parentReviewInput],
      repository,
    );
    expect(data(repairedCandidate).state).toMatchObject({ phase: 'verify' });
    expect(
      (await readNativePortableChange(parentPaths, 'parent')).acceptance.map(({ id }) => id),
    ).toEqual(parentState.acceptance.map(({ id }) => id));
  }, 300_000);
});

import { expect, it } from 'vitest';
import { stringify } from 'yaml';
import {
  nativeChildrenAcceptanceValidation,
  nativeChildrenIndexDrift,
  parseNativeChildrenContract,
} from '../../../domains/comet-native/native-children-contract.js';
import {
  confirmNativePortableAcceptance,
  prepareNativePortableShapeConfirmation,
} from '../../../domains/comet-native/native-loop-runtime.js';
import { createNativePortableState } from '../../../domains/comet-native/native-portable-state.js';

const acceptance = [
  { id: 'A1', source: 'brief.md', text: 'The existing interface remains available.' },
  {
    id: 'A2',
    source: 'specs/worker/spec.md',
    text: 'Worker output satisfies the requested behavior.',
  },
];
function validation() {
  const state = confirmNativePortableAcceptance({
    state: prepareNativePortableShapeConfirmation({
      state: createNativePortableState({ name: 'agent-decomposition', language: 'en' }),
      acceptance,
    }),
    acceptance,
  });
  return nativeChildrenAcceptanceValidation(state);
}
it('lets the Agent delegate specification acceptance before any failure while retaining parent-only criteria', () => {
  const options = validation();
  const source = stringify({
    schema: 'comet.native.children.v2',
    children: [{ name: 'worker', depends_on: [], covers: ['A2'] }],
  });
  const contract = parseNativeChildrenContract(source, ['A1', 'A2'], options);
  expect(contract.children[0].covers).toEqual(['A2']);
  expect(contract.acceptance_index).toEqual({
    A2: { source: acceptance[1].source, text: acceptance[1].text },
  });
  expect(nativeChildrenIndexDrift(contract, ['A1', 'A2'], options)).toBeNull();
});
it('reads delegated acceptance from the original parent catalog instead of requiring copied prose', () => {
  const source = stringify({
    schema: 'comet.native.children.v2',
    acceptance_index: {
      A1: { source: 'brief.md', text: 'A historical handoff summary.' },
      A2: { source: 'specs/worker/spec.md', text: 'Historical description.' },
    },
    children: [{ name: 'worker', depends_on: [], covers: ['A2'] }],
  });
  const contract = parseNativeChildrenContract(source, ['A1', 'A2'], validation());
  expect(contract.acceptance_index?.A1.text).toBe(acceptance[0].text);
  expect(contract.acceptance_index?.A2.text).toBe(acceptance[1].text);
  expect(nativeChildrenIndexDrift(contract, ['A1', 'A2'], validation())).toBeNull();
});
it('retains unknown-ID and dependency-cycle checks for Agent-selected task decomposition', () => {
  expect(() =>
    parseNativeChildrenContract(
      stringify({
        schema: 'comet.native.children.v2',
        children: [{ name: 'worker', depends_on: [], covers: ['A9'] }],
      }),
      ['A1', 'A2'],
      validation(),
    ),
  ).toThrow(/missing|unknown|acceptance/u);
  expect(() =>
    parseNativeChildrenContract(
      stringify({
        schema: 'comet.native.children.v2',
        children: [{ name: 'worker', depends_on: ['worker'], covers: ['A2'] }],
      }),
      ['A1', 'A2'],
      validation(),
    ),
  ).toThrow(/cycle/u);
});

